SELECT s.s_suppkey,s.s_name,s.s_address,s.s_phone,r.total_revenue FROM tpch_supplier s JOIN (SELECT l_suppkey AS supplier_no,SUM(l_extendedprice*(1-l_discount)) AS total_revenue FROM tpch_lineitem WHERE l_shipdate>='1996-01-01' AND l_shipdate<'1996-04-01' GROUP BY l_suppkey) r ON s.s_suppkey=r.supplier_no WHERE r.total_revenue=(SELECT MAX(rr.total_revenue) FROM (SELECT SUM(l_extendedprice*(1-l_discount)) AS total_revenue FROM tpch_lineitem WHERE l_shipdate>='1996-01-01' AND l_shipdate<'1996-04-01' GROUP BY l_suppkey) rr) ORDER BY s.s_suppkey;
